package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var a string
	fmt.Fscan(in, &a)

	if strings.ToUpper(a) == a {
		fmt.Fprintln(out, strings.ToLower(a))
	} else if strings.ToLower(a[:1])+strings.ToUpper(a[1:]) == a {
		fmt.Fprintln(out, strings.ToUpper(a[:1])+strings.ToLower(a[1:]))
	} else {
		fmt.Fprintln(out, a)
	}
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
	"unicode"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	if !scanner.Scan() {
		return
	}

	a := strings.TrimSpace(scanner.Text())
	runes := []rune(a)

	if strings.ToUpper(a) == a {
		fmt.Println(strings.ToLower(a))
	} else if len(runes) > 0 &&
		string(unicode.ToLower(runes[0]))+strings.ToUpper(string(runes[1:])) == a {
		fmt.Println(string(unicode.ToUpper(runes[0])) + strings.ToLower(string(runes[1:])))
	} else {
		fmt.Println(a)
	}
}

